import { Entity, PrimaryGeneratedColumn, Column } from "typeorm";

@Entity()
export class User {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  email: string;

  @Column({ default: true })
  isActive: boolean;
}

// Repository를 통한 조회
const userRepo = dataSource.getRepository(User);
const users = await userRepo.find({ where: { isActive: true } });
